	/**
	 *  How many notes the list holds in all; the window asks for the
	 *  others (`replace_page`).
	 */
	listed: number,
	/**  "{n} note(s) could not be searched.", when some could not. */
	unreadable: string | null,
	/**  Step 3: what is chosen to be replaced now. */
